                        entries.forEach(entry => {
                            items.push({
                                id: `${name}::${entry.uid}`,
                                worldbook: name,
                                entry,
                                enabled: !!entry.enabled,
                                label: `${name} / ${entry.name || `#${entry.uid}`}`,
