                    const aNorm = a.worldbook.replace(/\s+/g, '');
                    const bNorm = b.worldbook.replace(/\s+/g, '');
                    const aScore = aNorm === normalizedDefault || aNorm === normalizedAlt ? 0 : 1;
                    const bScore = bNorm === normalizedDefault || bNorm === normalizedAlt ? 0 : 1;
