        function extractTagContent(source, tag) {
            const re = new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`, 'gi');
            let last = '';
            let match;
            while ((match = re.exec(source)) !== null) {
                last = match[1];
            }
            return last ? last.trim() : '';
        }
        function extractTagContents(source, tag) {
            const re = new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`, 'gi');
            const list = [];
            let match;
            while ((match = re.exec(source)) !== null) {
                list.push(match[1].trim());
            }
            return list;
        }
        function extractYamlBlock(source) {
            const re = /```yaml\s*([\s\S]*?)```/i;
            const match = source.match(re);
            return match ? match[1].trim() : source.trim();
        }
        function extractEnglishNameFromYaml(source) {
            const match = source.match(/english name:\s*([^\n\r]+)/i);
            return match ? String(match[1]).trim() : '';
        }
        function stripCodeFence(source) {
            return source
                .replace(/```(?:json|yaml)?/gi, '')
                .replace(/```/g, '')
                .trim();
        }
        function extractJsonBlock(source, startChar, endChar) {
            const start = source.indexOf(startChar);
            if (start === -1)
                return '';
            let depth = 0;
            let inString = false;
            let escaped = false;
            for (let i = start; i < source.length; i += 1) {
                const ch = source[i];
                if (inString) {
                    if (escaped) {
                        escaped = false;
                    }
                    else if (ch === '\\') {
                        escaped = true;
                    }
                    else if (ch === '"') {
                        inString = false;
                    }
                    continue;
                }
                if (ch === '"') {
                    inString = true;
                    continue;
                }
                if (ch === startChar)
                    depth += 1;
                if (ch === endChar)
                    depth -= 1;
                if (depth === 0) {
                    return source.slice(start, i + 1).trim();
                }
            }
            return '';
        }
        function extractRoleJsonFallback(source) {
            const fenced = extractTagContent(source, 'ROLE_JSON');
            if (fenced)
                return fenced;
            const codeBlock = extractTagContent(source, 'json');
            if (codeBlock)
                return codeBlock;
            return extractJsonBlock(source, '{', '}');
        }
        function extractKeysFallback(source) {
            const fenced = extractTagContent(source, 'WB_KEYS');
