                return blocks;
            const listBlock = extractTagContent(source, 'ROLE_JSON_LIST');
            if (listBlock) {
                try {
                    const parsed = JSON.parse(stripCodeFence(listBlock));
                    if (Array.isArray(parsed)) {
                        return parsed.map(item => JSON.stringify(item));
                    }
                }
